// Runs Patrik Rak's z80test conformance suite (tests/data/z80test) inside the
// emulator and checks the result line the suite prints on screen.
//
// The suite is distributed as a TAP file meant to be loaded from BASIC, and the
// real Spectrum ROM cannot be shipped with the repository. Instead the code
// block is injected straight into RAM and started with the PC, which works
// because the suite only needs three things from its host: `RST 0x10` to print
// a character, `0x1601` (CHAN-OPEN) to exist, and IM 1 interrupts to tick.
// tests/data/test48.rom, generated by tools/make_test_rom.py, provides exactly
// that and nothing else.

#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>

#include "test_framework.h"

#include "core/machine.h"
#include "formats/tape.h"

using rainbow::Machine;
using rainbow::MachineType;
using rainbow::u16;
using rainbow::u8;

namespace {

// Where the synthetic ROM parks a finished program: the idle loop at 0x0123
// reads the keyboard, sets the border and halts, so a halted CPU means the
// suite has returned.
constexpr u16 kIdle = 0x0123;
constexpr u16 kStackTop = 0x7FF0;
constexpr u16 kGlyphBase = 0x3D00;

std::vector<u8> readFile(const std::string& path) {
  std::vector<u8> data;
  std::FILE* file = std::fopen(path.c_str(), "rb");
  if (file == nullptr) return data;
  u8 buffer[0x4000];
  size_t got;
  while ((got = std::fread(buffer, 1, sizeof buffer, file)) > 0) {
    data.insert(data.end(), buffer, buffer + got);
  }
  std::fclose(file);
  return data;
}

// The suite prints one line per test and keeps the result on the last rows, so
// the runner has to read the screen back. Each cell is matched against the
// glyph shapes the ROM keeps at 0x3D00 instead of being compared pixel by pixel
// with a character generator the synthetic ROM would otherwise have to expose.
class ScreenReader {
public:
  explicit ScreenReader(Machine& machine) : machine_(machine) {
    for (int ch = 32; ch < 128; ++ch) {
      for (int line = 0; line < 8; ++line) {
        glyphs_[(ch - 32) * 8 + line] =
            machine.memRead(u16(kGlyphBase + (ch - 32) * 8 + line), 0);
      }
    }
  }

  std::string row(int textRow) {
    const int y = textRow * 8;
    const u16 base = u16(0x4000 + ((y & 0xC0) << 5) + ((y & 0x07) << 8) + ((y & 0x38) << 2));
    std::string text;
    for (int column = 0; column < 32; ++column) {
      u8 pixels[8];
      for (int line = 0; line < 8; ++line) {
        pixels[line] = machine_.memRead(u16(base + column + (line << 8)), 0);
      }
      text += char(match(pixels));
    }
    while (!text.empty() && text.back() == ' ') text.pop_back();
    return text;
  }

private:
  char match(const u8 (&pixels)[8]) const {
    for (int ch = 32; ch < 128; ++ch) {
      const u8* glyph = &glyphs_[(ch - 32) * 8];
      int line = 0;
      while (line < 8 && glyph[line] == pixels[line]) ++line;
      if (line == 8) return char(ch);
    }
    return '?';
  }

  Machine& machine_;
  u8 glyphs_[96 * 8] = {};
};

struct RunResult {
  bool skipped = false; // the ROM or the suite data is not available
  bool finished = false;
  bool passed = false;
  int failures = -1;
  std::vector<std::string> screen;
};

// Copies the suite's CODE block into RAM and starts it. TAP data blocks carry a
// leading flag byte and a trailing checksum that the loader strips, so both are
// cut here as well.
bool injectSuite(Machine& machine, const std::vector<u8>& tap, std::string& error) {
  rainbow::formats::TapeImage image;
  if (!rainbow::formats::parseTap(tap, image, error)) return false;

  u16 loadAddress = 0x8000;
  std::vector<u8> payload;
  for (size_t i = 0; i + 1 < image.blocks.size(); ++i) {
    const auto& header = image.blocks[i];
    if (!header.isHeader() || header.data.size() < 17) continue;
    if (header.data[1] != 3) continue; // 3 = CODE
    loadAddress = u16(header.data[14] | (header.data[15] << 8));
    const auto& body = image.blocks[i + 1];
    if (body.kind == rainbow::formats::TapeBlock::Kind::Data && body.data.size() > 2) {
      payload.assign(body.data.begin() + 1, body.data.end() - 1);
    }
  }
  if (payload.empty()) {
    error = "the TAP file has no CODE block";
    return false;
  }
  if (size_t(loadAddress) + payload.size() > 0x10000) {
    error = "the CODE block does not fit in 64K";
    return false;
  }

  for (size_t i = 0; i < payload.size(); ++i) {
    machine.memWrite(u16(loadAddress + i), payload[i], 0);
  }

  auto& registers = machine.cpu().regs();
  registers.sp = kStackTop;
  registers.pc = loadAddress;
  registers.iff1 = false;
  registers.iff2 = false;
  registers.im = 1;
  registers.halted = false;
  // The suite returns through the stack when it is done; send it to the idle
  // loop so the result stays on screen.
  machine.memWrite(kStackTop, u8(kIdle & 0xFF), 0);
  machine.memWrite(u16(kStackTop + 1), u8(kIdle >> 8), 0);
  return true;
}

RunResult runSuite(const std::string& tapName, int maxFrames) {
  RunResult result;

  Machine machine(MachineType::Spectrum48);
  if (!machine.loadRom(RAINBOW_SOURCE_DIR "/tests/data/test48.rom")) {
    result.skipped = true;
    return result;
  }

  const std::vector<u8> tap =
      readFile(std::string(RAINBOW_SOURCE_DIR "/tests/data/z80test/") + tapName);
  if (tap.empty()) {
    result.skipped = true;
    return result;
  }

  std::string error;
  if (!injectSuite(machine, tap, error)) {
    result.skipped = true;
    return result;
  }

  machine.setVideoEnabled(false);
  for (int frame = 0; frame < maxFrames; ++frame) {
    machine.runFrame();
    if (machine.cpu().regs().halted) break;
  }

  ScreenReader reader(machine);
  for (int row = 0; row < 24; ++row) {
    const std::string line = reader.row(row);
    const size_t at = line.find("Result: ");
    if (at == std::string::npos) continue;
    result.finished = true;
    result.passed = line.find("all tests passed") != std::string::npos;
    const size_t failed = line.find(" tests failed");
    if (failed != std::string::npos) {
      result.failures = std::atoi(line.substr(at + 8, failed - (at + 8)).c_str());
    }
    break;
  }
  for (int r = 0; r < 24; ++r) result.screen.push_back(reader.row(r));
  return result;
}

RunResult runSuiteOrFail(const char* tapName, int maxFrames = 60000) {
  const RunResult result = runSuite(tapName, maxFrames);
  if (result.skipped) return result;
  if (!result.finished) {
    ::testing::fail(__FILE__, __LINE__, std::string(tapName) + " did not reach a result line");
  }
  return result;
}

std::string screenDump(const RunResult& result) {
  std::string report;
  for (const std::string& line : result.screen) report += "  " + line + "\n";
  return report;
}

} // namespace

// The documented flag suite is the one the emulator must always satisfy.
TEST(z80test_documented_flags_all_pass) {
  const RunResult result = runSuiteOrFail("z80doc.tap");
  if (result.skipped) return;
  if (result.finished && !result.passed) {
    ::testing::fail(__FILE__, __LINE__,
                    "z80doc reported " + std::to_string(result.failures) + " failing test(s):\n" +
                        screenDump(result));
  }
}

// Same vectors, but every flag is compared, so this one also pins the
// undocumented F3/F5 behaviour of the block instructions.
TEST(z80test_documented_and_undocumented_flags_all_pass) {
  const RunResult result = runSuiteOrFail("z80docflags.tap");
  if (result.skipped) return;
  if (result.finished && !result.passed) {
    ::testing::fail(__FILE__, __LINE__,
                    "z80docflags reported " + std::to_string(result.failures) +
                        " failing test(s):\n" + screenDump(result));
  }
}

// The full suite compares registers as well and checks the undocumented flags
// of every instruction. Six of its 160 cases are still off: the two SCF+CCF
// and CCF+SCF sequences, where the suite derives its vectors from a
// pseudo-random combination of both instructions, and the four `->NOP'` block
// instruction cases, which copy over their own opcode and then depend on how
// an undefined `ED 00` behaves. The test guards against regressions outside
// that set.
TEST(z80test_full_flag_suite_has_no_new_regressions) {
  const RunResult result = runSuiteOrFail("z80full.tap");
  if (result.skipped || !result.finished || result.passed) return;
  if (result.failures > 6) {
    ::testing::fail(__FILE__, __LINE__,
                    "z80full reported " + std::to_string(result.failures) +
                        " failing test(s), more than the 6 known gaps:\n" + screenDump(result));
  }
}

// Same vectors as z80full but comparing the flags only. It fails on the same
// six cases, so it adds nothing the suite above does not already cover — it is
// kept because it is the cheap way to tell a flag regression from a register
// one when z80full starts reporting something new.
TEST(z80test_flag_only_suite_has_no_new_regressions) {
  const RunResult result = runSuiteOrFail("z80flags.tap");
  if (result.skipped || !result.finished || result.passed) return;
  if (result.failures > 6) {
    ::testing::fail(__FILE__, __LINE__,
                    "z80flags reported " + std::to_string(result.failures) +
                        " failing test(s), more than the 6 known gaps:\n" + screenDump(result));
  }
}

// The MEMPTR suite repeats every case with a `BIT n,(HL)` right after it, which
// is the only way to observe the internal WZ register: BIT takes F3/F5 from the
// high half of WZ. Seventeen cases are still off. Four are the `->NOP' block
// instructions that share the undefined `ED 00` behaviour with z80full, two are
// SCF+CCF/CCF+SCF, and the rest are WZ values the emulator does not model yet:
// ADD/ADC/SBC HL,rr and ADD IX/IY,rr, LDIR/LDDR, CPIR/CPDR, OUTI/OUTD, the
// conditional JR and DJNZ.
TEST(z80test_memptr_suite_has_no_new_regressions) {
  const RunResult result = runSuiteOrFail("z80memptr.tap");
  if (result.skipped || !result.finished || result.passed) return;
  if (result.failures > 17) {
    ::testing::fail(__FILE__, __LINE__,
                    "z80memptr reported " + std::to_string(result.failures) +
                        " failing test(s), more than the 17 known gaps:\n" + screenDump(result));
  }
}
